<script setup lang="ts">
import {memberPalettePreset} from '../../../../api/src/core/decoration-framework.mjs'
import type {DecorationBlock,DecorationOptions} from '../../../../api/src/core/decoration-types'
import {decorationOptions} from '../../../../api/src/core/decoration-options.mjs'
import DecorationColorField from './DecorationColorField.vue'
import DecorationSettingRange from './DecorationSettingRange.vue'
const props=defineProps<{disabled?:boolean;imageUrl:(id:string)=>string}>(),block=defineModel<DecorationBlock>({required:true}),o=computed(()=>decorationOptions(block.value))
function set(key:keyof DecorationOptions,value:unknown){if(!props.disabled)block.value.options={...o.value,[key]:value}}
const activityColors=[{key:'titleColor',label:'标题颜色'},{key:'subtitleColor',label:'副标题颜色'},{key:'subtitleBackground',label:'副标题背景'},{key:'subtitleBackgroundEnd',label:'副标题渐变末色'}] as const
const searchColors=[{key:'searchColor',label:'搜索文字'},{key:'searchBackground',label:'搜索框背景'},{key:'searchButtonColor',label:'按钮文字'},{key:'searchButtonBackground',label:'按钮背景'},{key:'headerColor',label:'地址文字'},{key:'headerIconColor',label:'返回图标'},{key:'tabColor',label:'标签文字'},{key:'tabSelectedColor',label:'标签选中'},{key:'fixedTabColor',label:'吸顶标签文字'},{key:'fixedTabSelectedColor',label:'吸顶标签选中'},{key:'fixedBackground',label:'吸顶背景'}] as const
</script>
<template><section v-if="['membership','member-level','member-overview'].includes(block.type)" class="reference-style"><h3>会员权益</h3><div class="member-palette-field"><span>配色方案</span><div class="member-palette-options"><button v-for="palette in [{value:'classic',label:'纯净白',color:'#ffffff'},{value:'soft',label:'雾蓝',color:'#f0f4fc'},{value:'dark',label:'深蓝金',color:'#222e40'},{value:'gold',label:'金色',color:'#fff3df'}]" :key="palette.value" type="button" :class="{active:o.memberSurface===palette.color}" :aria-pressed="o.memberSurface===palette.color" :disabled="disabled" @click="!disabled&&(block.options={...o,...memberPalettePreset(palette.value)})"><i :style="{background:palette.color}"/>{{palette.label}}</button></div></div><label class="toggle">显示会员等级<USwitch :model-value="o.showMemberStatus" :disabled="disabled" @update:model-value="set('showMemberStatus',$event)"/></label><label class="toggle">主题配色<USwitch :model-value="o.memberTheme" :disabled="disabled" @update:model-value="set('memberTheme',$event)"/></label><DecorationColorField :model-value="o.memberAccent" label="强调颜色" :disabled="disabled||o.memberTheme" @update:model-value="set('memberAccent',$event)"/><DecorationColorField :model-value="o.memberSurface" label="卡片背景" :disabled="disabled" @update:model-value="set('memberSurface',$event)"/><DecorationColorField :model-value="o.memberText" label="主要文字" :disabled="disabled" @update:model-value="set('memberText',$event)"/><DecorationColorField :model-value="o.memberMuted" label="辅助文字" :disabled="disabled" @update:model-value="set('memberMuted',$event)"/><DecorationSettingRange :model-value="o.memberRadius" label="卡片圆角" :max="40" :disabled="disabled" @update:model-value="set('memberRadius',$event)"/></section><section v-if="block.type==='activity'" class="reference-style"><h3>标题样式</h3><DecorationColorField v-for="f in activityColors" :key="f.key" :model-value="o[f.key]" :label="f.label" :disabled="disabled" @update:model-value="set(f.key,$event)"/><h3>板块样式</h3><UFormField label="标题粗细"><USelect :model-value="o.activityWeight" :items="[{label:'常规',value:'normal'},{label:'加粗',value:'bold'}]" :disabled="disabled" class="w-full" @update:model-value="set('activityWeight',$event)"/></UFormField><label class="toggle">按钮文字斜体<USwitch :model-value="o.buttonItalic" :disabled="disabled" @update:model-value="set('buttonItalic',$event)"/></label><DecorationSettingRange :model-value="o.imageRadiusTop" label="元素上圆角" :max="50" :disabled="disabled" @update:model-value="set('imageRadiusTop',$event)"/><DecorationSettingRange :model-value="o.imageRadiusBottom" label="元素下圆角" :max="50" :disabled="disabled" @update:model-value="set('imageRadiusBottom',$event)"/></section>
<section v-if="['search','search-box'].includes(block.type)" class="reference-style"><h3>搜索与分类颜色</h3><DecorationColorField v-for="f in block.type==='search-box'?searchColors.slice(0,4):searchColors" :key="f.key" :model-value="o[f.key]" :label="f.label" :disabled="disabled" @update:model-value="set(f.key,$event)"/><template v-if="block.type==='search'"><label class="toggle">轮播背景渐变<USwitch :model-value="o.searchGradient" :disabled="disabled" @update:model-value="set('searchGradient',$event)"/></label><UFormField label="轮播样式"><USelect :model-value="o.swiperStyle" :items="[{label:'风格1 · 两侧露出',value:'peek'},{label:'风格2 · 两侧留白',value:'normal'},{label:'风格3 · 通栏',value:'full'}]" :disabled="disabled" class="w-full" @update:model-value="set('swiperStyle',$event)"/></UFormField><DecorationSettingRange :model-value="o.imageRadiusTop" label="轮播上圆角" :max="50" :disabled="disabled" @update:model-value="set('imageRadiusTop',$event)"/><DecorationSettingRange :model-value="o.imageRadiusBottom" label="轮播下圆角" :max="50" :disabled="disabled" @update:model-value="set('imageRadiusBottom',$event)"/></template></section>
<section v-if="block.type==='showcase'" class="reference-style"><h3>模块圆角</h3><DecorationSettingRange :model-value="o.imageRadiusTop" label="模块上圆角" :max="50" :disabled="disabled" @update:model-value="set('imageRadiusTop',$event)"/><DecorationSettingRange :model-value="o.imageRadiusBottom" label="模块下圆角" :max="50" :disabled="disabled" @update:model-value="set('imageRadiusBottom',$event)"/></section></template>
<style scoped>.reference-style{display:grid;gap:16px}.reference-style h3{font-size:13px;font-weight:600}.toggle{display:flex;align-items:center;justify-content:space-between;font-size:12px}.member-palette-field{display:grid;gap:10px;font-size:12px}.member-palette-options{display:flex;gap:8px}.member-palette-options button{display:flex;align-items:center;gap:6px;padding:7px 9px;border:1px solid var(--ui-border);border-radius:6px;white-space:nowrap}.member-palette-options button.active{border-color:var(--ui-primary);color:var(--ui-primary)}.member-palette-options i{width:13px;height:13px;border:1px solid #94a3b840;border-radius:50%}</style>
